={{ (() => {
  const body = $('Webhook').first().json.body ?? {};
  const textoAtual = $json.body?.content || $json.content?.parts?.[0]?.text || $json.output || body.content || '';
  return {
    contato: body.sender?.phone_number?.replace('+', '') || '',
    id_chatwoot: body.messages?.[0]?.id || '',
    id: body.source_id || '',
    texto: textoAtual,
    timestamp: body.conversation?.last_activity_at || body.created_at || ''
  };
})() }}

